226	+/* Two pixels at a time: `p` is 16-bit and not always 4-byte aligned. */
227	+static void fill_pixels(uint16_t *p, uint16_t v, int n) {
228	+  if (n > 0 && ((uintptr_t)p & 2)) {
229	+    *p++ = v;
230	+    n--;
231	+  }
232	+  uint32_t *q = (uint32_t *)p;
233	+  const uint32_t pair = ((uint32_t)v << 16) | v;
234	+  for (; n >= 2; n -= 2) *q++ = pair;
235	+  if (n) *(uint16_t *)q = v;
